CREATE TABLE "assignments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "item_id" bigint NOT NULL,
  "holder_name" text NOT NULL,
  "worker_name" text NOT NULL,
  "state" text NOT NULL,
  "expires_at" bigint NOT NULL,
  "created_at" bigint NOT NULL,
  "changed_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("id")
);

CREATE INDEX "assignments_holder" ON "assignments" (holder_name, id);
CREATE INDEX "assignments_worker" ON "assignments" (worker_name, id);
CREATE INDEX "assignments_item" ON "assignments" (item_id);

CREATE TABLE "jobs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "item_id" bigint NOT NULL,
  "lease_id" bigint NOT NULL,
  "holder_name" text NOT NULL,
  "assignment_id" bigint NOT NULL,
  "worker_name" text NOT NULL,
  "session_id" text,
  "run_id" bigint,
  "run_name" text,
  "room_id" bigint,
  "state" text NOT NULL,
  "outcome" text,
  "report" text,
  "token_count" bigint NOT NULL DEFAULT 0,
  "started_at" bigint NOT NULL,
  "ended_at" bigint,
  "prompt" text NOT NULL,
  "prompt_english" text,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("id")
);

CREATE INDEX "jobs_holder" ON "jobs" (holder_name, id);
CREATE INDEX "jobs_worker" ON "jobs" (worker_name, id);
CREATE INDEX "jobs_room" ON "jobs" (room_id, id);
CREATE INDEX "jobs_state" ON "jobs" (state);

CREATE TABLE "session_work" (
  "session_id" text,
  "item_id" bigint,
  "results" text NOT NULL DEFAULT '[]',
  "changed_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id")
);

CREATE TABLE "session_loads" (
  "session_id" text,
  "documents" text NOT NULL DEFAULT '[]',
  "changed_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id")
);

CREATE TABLE "session_summaries" (
  "agent" text,
  "text" text NOT NULL,
  "changed_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("agent")
);
